package com.hmdp.ai.runtime.tool.skill;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.run.ExecutionContext;import com.hmdp.ai.port.*;import com.hmdp.ai.runtime.tool.*;import com.hmdp.ai.runtime.tool.skill.dto.ShopAnalysisData;import org.springframework.stereotype.Component;
@Component @AgentSkill(code="get-shop-quality-summary") public class GetShopQualitySummarySkill extends ShopSkillSupport implements LocalSkill {public GetShopQualitySummarySkill(ShopDataPort s,ReviewDataPort r,ObjectMapper m){super(s,r,m);}@Override public JsonNode execute(ExecutionContext c,JsonNode in){long id=shopId(in);int min=Math.max(0,in.path("minLiked").asInt(5)),limit=Math.max(1,Math.min(50,in.path("limit").asInt(10)));return json(new ShopAnalysisData(shops.getShop(id),shops.getReviewCount(id),evidence(reviews.findQualityReviews(id,min,limit))));}}
